    "style": "technical exploded view diagram, all structural components separated and floating in space",
    "direction": "outward radial separation from center, as if blasted by magic force",
    "spacing": "clear readable gaps between all layers, no overlapping"
  },

  "separated_components": {
    "layer_1_roof_top": {
      "parts": ["entire roof assembly with shingles", "exposed rafters and trusses", "ridge beam"],
      "position": "floating highest, near top of frame"
    },
    "layer_2_second_floor": {
      "parts": ["second floor exterior wall panels (all 4 sides separated)", "upper window frames with broken glass", "shutters"],
      "position": "floating upper-middle zone"
    },
    "layer_3_interior_skeleton": {
      "parts": ["wooden wall studs and framing", "floor joists", "ceiling beams", "interior staircase"],
      "position": "center zone, the exposed skeleton"
    },
    "layer_4_first_floor": {
      "parts": ["first floor exterior wall panels (all 4 sides separated)", "front door and frame", "lower windows", "porch columns and railings"],
      "position": "floating lower-middle zone"
    },
    "layer_5_foundation_base": {
      "parts": ["stone foundation blocks separated", "porch steps", "floor platform"],
      "position": "lowest layer, above the hand"
    }
