  "magic_hand_transformed": {
    "position": "SAME position as first frame — bottom center of frame",
    "gesture": "CLENCHED FIST, fingers curled tight, power pose",
    "appearance": "same human hand, intense magical energy burst radiating outward",
    "magic_effect": "energy shockwave lines connecting fist to exploded house pieces, glowing particles",
    "sleeve": "same dark robe sleeve"
