  "critical_rules": {
    "camera": "IDENTICAL to original — same angle, same focal length, NO movement",
    "background": "PIXEL-PERFECT UNCHANGED — same sky, grass, trees, environment",
    "aspect_ratio": "MUST remain 9:16 vertical — DO NOT switch to landscape",
    "lighting": "PRESERVED with enhanced magical glow from fist",
    "hand_position": "SAME LOCATION — only gesture changes (open palm → clenched fist)",
    "textures": "ALL weathered/broken textures maintained on every piece",
    "exterior_casing": "ALL exterior surfaces visible as separated floating pieces"
